import fs from 'fs';
import http from 'http';
import path from 'path';
import { AddressInfo } from 'net';
import { WebSocket, WebSocketServer } from 'ws';
import chokidar, { FSWatcher } from 'chokidar';
import { build, BuildOptions } from './ssg';

export interface ServeOptions extends BuildOptions {
  port?: number;
  host?: string;
}

export const DEFAULT_SERVE_PORT = 3000;
export const LIVE_RELOAD_PATH = '/__live_reload';

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html',
  '.htm': 'text/html',
  '.css': 'text/css',
  '.js': 'application/javascript',
  '.mjs': 'application/javascript',
  '.json': 'application/json',
  '.map': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain',
  '.xml': 'application/xml',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.otf': 'font/otf',
  '.pdf': 'application/pdf',
  '.md': 'text/markdown',
};

function liveReloadScript(): string {
  return `\n<script>
(function () {
  var ws;
  var retries = 0;
  function connect() {
    ws = new WebSocket('ws://' + location.host + '${LIVE_RELOAD_PATH}');
    ws.onmessage = function (event) {
      if (event.data === 'reload') {
        location.reload();
      }
    };
    ws.onclose = function () {
      if (retries < 60) {
        retries += 1;
        setTimeout(connect, 500);
      }
    };
    ws.onopen = function () {
      retries = 0;
    };
  }
  connect();
})();
</script>`;
}

export function injectLiveReload(html: string): string {
  const script = liveReloadScript();
  if (/<\/body>/i.test(html)) {
    return html.replace(/<\/body>/i, `${script}\n</body>`);
  }
  if (/<\/html>/i.test(html)) {
    return html.replace(/<\/html>/i, `${script}\n</html>`);
  }
  return html + script;
}

export interface DevServer {
  server: http.Server;
  wss: WebSocketServer;
  port: number;
  watcher: FSWatcher;
  rebuild: () => void;
  close: () => Promise<void>;
}

export function startDevServer(options: ServeOptions = {}): DevServer {
  const outputDir = path.resolve(options.outputDir ?? 'dist');
  const contentDir = path.resolve(options.contentDir ?? 'content');
  const templateDir = path.resolve(options.templateDir ?? 'templates');
  const port = options.port ?? DEFAULT_SERVE_PORT;
  const host = options.host ?? '127.0.0.1';

  let rebuilding = false;
  let pending = false;

  function broadcastReload(): void {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  }

  function rebuild(): void {
    if (rebuilding) {
      pending = true;
      return;
    }
    rebuilding = true;
    try {
      const pages = build({
        contentDir,
        outputDir,
        templateDir,
        defaultTemplate: options.defaultTemplate,
        defaultLayout: options.defaultLayout,
      });
      console.log(`[ssg] rebuilt ${pages.length} page(s)`);
      broadcastReload();
    } catch (err) {
      console.error('[ssg] rebuild failed:', err instanceof Error ? err.message : err);
    } finally {
      rebuilding = false;
      if (pending) {
        pending = false;
        rebuild();
      }
    }
  }

  const server = http.createServer((req, res) => {
    const requestUrl = new URL(req.url ?? '/', `http://${req.headers.host ?? 'localhost'}`);
    let pathname: string;
    try {
      pathname = decodeURIComponent(requestUrl.pathname);
    } catch {
      res.writeHead(400);
      res.end('Bad Request');
      return;
    }

    let filePath = path.join(outputDir, path.normalize(pathname));
    if (!filePath.startsWith(outputDir + path.sep)) {
      res.writeHead(403);
      res.end('Forbidden');
      return;
    }

    if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
      filePath = path.join(filePath, 'index.html');
    } else if (!path.extname(filePath) && fs.existsSync(`${filePath}.html`)) {
      filePath = `${filePath}.html`;
    }

    if (!fs.existsSync(filePath) || fs.statSync(filePath).isDirectory()) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Not Found');
      return;
    }

    const ext = path.extname(filePath).toLowerCase();
    const mime = MIME_TYPES[ext] ?? 'application/octet-stream';
    let body = fs.readFileSync(filePath);

    if (mime === 'text/html') {
      body = Buffer.from(injectLiveReload(body.toString('utf8')), 'utf8');
    }

    res.writeHead(200, { 'Content-Type': `${mime}; charset=utf-8` });
    res.end(body);
  });

  const wss = new WebSocketServer({ server, path: LIVE_RELOAD_PATH });

  server.listen(port, host);

  const watcher = chokidar.watch([contentDir, templateDir], { ignoreInitial: true });
  watcher.on('all', () => {
    rebuild();
  });

  let boundPort = port;
  server.once('listening', () => {
    const address = server.address() as AddressInfo | null;
    if (address && typeof address === 'object') {
      boundPort = address.port;
    }
  });

  const close = () =>
    new Promise<void>((resolve, reject) => {
      for (const client of wss.clients) {
        client.terminate();
      }
      watcher.close();
      wss.close();
      server.close((err) => (err ? reject(err) : resolve()));
    });

  return {
    server,
    wss,
    get port() {
      return boundPort;
    },
    watcher,
    rebuild,
    close,
  };
}

#!/usr/bin/env node
import { build, BuildOptions } from './ssg';
import { startDevServer, DEFAULT_SERVE_PORT } from './serve';

const DEFAULT_COMMAND = 'build';

interface CliOptions extends BuildOptions {
  port?: number;
}

function printUsage(): void {
  console.log(`Usage:
  ssg build [options]
  ssg serve [options]

Commands:
  build   Generate the static site into the output directory
  serve   Run a live-reload development server

Options:
  --content <dir>     Source directory for Markdown files (default: ./content)
  --output <dir>      Output directory for generated HTML (default: ./dist)
  --templates <dir>   Directory for Handlebars templates (default: ./templates)
  --port <number>     Port for the dev server (default: ${DEFAULT_SERVE_PORT})
  --help              Show this help`);
}

function parseArgs(argv: string[]): { command: string; options: CliOptions; help: boolean } {
  const options: CliOptions = {};
  let help = false;
  let command = DEFAULT_COMMAND;

  let idx = 0;
  while (idx < argv.length) {
    const arg = argv[idx];
    switch (arg) {
      case '--help':
      case '-h':
        help = true;
        idx += 1;
        break;
      case '--content':
        options.contentDir = argv[idx + 1];
        idx += 2;
        break;
      case '--output':
        options.outputDir = argv[idx + 1];
        idx += 2;
        break;
      case '--templates':
        options.templateDir = argv[idx + 1];
        idx += 2;
        break;
      case '--port':
        options.port = Number.parseInt(argv[idx + 1], 10);
        idx += 2;
        break;
      default:
        if (arg.startsWith('-')) {
          idx += 1;
        } else {
          command = arg;
          idx += 1;
        }
    }
  }

  return { command, options, help };
}

function main(): void {
  const { command, options, help } = parseArgs(process.argv.slice(2));

  if (help) {
    printUsage();
    return;
  }

  if (command === 'build') {
    const pages = build(options);
    console.log(`Generated ${pages.length} page(s) into ${options.outputDir ?? './dist'}`);
    return;
  }

  if (command === 'serve') {
    const dev = startDevServer(options);
    const port = options.port ?? DEFAULT_SERVE_PORT;
    console.log(`[ssg] Dev server running at http://localhost:${port}`);
    console.log(`[ssg] Serving ./dist; watching content/ and templates/ for changes`);
    process.on('SIGINT', () => {
      dev.close().then(() => process.exit(0));
    });
    return;
  }

  printUsage();
  process.exitCode = 1;
}

if (require.main === module) {
  main();
}

export { parseArgs, main };

import fs from 'fs';
import os from 'os';
import path from 'path';
import http from 'http';
import { AddressInfo } from 'net';
import { WebSocket } from 'ws';
import { startDevServer, injectLiveReload, DevServer } from '../src/serve';
import { build } from '../src/ssg';

function makeTempRoot(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

function writeTree(root: string, files: Record<string, string>): void {
  for (const [rel, content] of Object.entries(files)) {
    const filePath = path.join(root, rel);
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, content, 'utf8');
  }
}

function listen(server: http.Server): Promise<number> {
  return new Promise((resolve) => {
    server.once('listening', () => {
      const address = server.address() as AddressInfo | null;
      resolve(address ? address.port : 0);
    });
  });
}

function waitForMessage(socket: WebSocket, timeout = 8000): Promise<string> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      socket.off('message', onMessage);
      reject(new Error('timed out waiting for websocket message'));
    }, timeout);
    function onMessage(data: WebSocket.RawData): void {
      clearTimeout(timer);
      socket.off('message', onMessage);
      resolve(data.toString());
    }
    socket.on('message', onMessage);
  });
}

function waitForFile(filePath: string, timeout = 8000): Promise<void> {
  return new Promise((resolve, reject) => {
    const start = Date.now();
    const timer = setInterval(() => {
      if (fs.existsSync(filePath)) {
        clearInterval(timer);
        resolve();
      } else if (Date.now() - start > timeout) {
        clearInterval(timer);
        reject(new Error(`timed out waiting for ${filePath}`));
      }
    }, 50);
  });
}

describe('injectLiveReload', () => {
  it('injects a WebSocket script before the closing body tag', () => {
    const html = '<!DOCTYPE html>\n<html><head></head><body><h1>hi</h1></body></html>';
    const out = injectLiveReload(html);
    expect(out).toContain('<script');
    expect(out).toContain('WebSocket');
    expect(out).toContain('/__live_reload');
    expect(out.indexOf('WebSocket')).toBeGreaterThan(out.indexOf('</body>') - 4000);
    expect(out.indexOf('<script')).toBeLessThan(out.indexOf('</body>'));
  });

  it('appends the script when there is no body tag', () => {
    const out = injectLiveReload('plain text');
    expect(out).toContain('plain text');
    expect(out).toContain('WebSocket');
  });
});

describe('dev server', () => {
  let root: string;
  let contentDir: string;
  let templateDir: string;
  let outputDir: string;
  let dev: DevServer;

  afterEach(async () => {
    if (dev) {
      await dev.close();
      dev = undefined as unknown as DevServer;
    }
    if (root) {
      fs.rmSync(root, { recursive: true, force: true });
    }
  });

  beforeEach(() => {
    root = makeTempRoot('ssg-serve-');
    contentDir = path.join(root, 'content');
    templateDir = path.join(root, 'templates');
    outputDir = path.join(root, 'dist');
  });

  it('serves built pages with the live reload script injected', async () => {
    writeTree(root, {
      'content/a.md': '---\ntitle: A\n---\nBody text.',
    });
    build({ contentDir, outputDir, templateDir });

    dev = startDevServer({ contentDir, outputDir, templateDir, port: 0 });
    const port = await listen(dev.server);

    const res = await fetch(`http://127.0.0.1:${port}/a.html`);
    expect(res.status).toBe(200);
    const body = await res.text();
    expect(body).toContain('Body text.');
    expect(body).toContain('WebSocket');
    expect(body).toContain('/__live_reload');
  });

  it('serves index.html at the root', async () => {
    writeTree(root, {
      'content/a.md': '---\ntitle: A\n---\nBody.',
    });
    build({ contentDir, outputDir, templateDir });

    dev = startDevServer({ contentDir, outputDir, templateDir, port: 0 });
    const port = await listen(dev.server);

    const res = await fetch(`http://127.0.0.1:${port}/`);
    expect(res.status).toBe(200);
    const body = await res.text();
    expect(body).toContain('index.html');
    expect(body).toContain('WebSocket');
  });

  it('returns 404 for missing files', async () => {
    writeTree(root, {
      'content/a.md': '---\ntitle: A\n---\nBody.',
    });
    build({ contentDir, outputDir, templateDir });

    dev = startDevServer({ contentDir, outputDir, templateDir, port: 0 });
    const port = await listen(dev.server);

    const res = await fetch(`http://127.0.0.1:${port}/nope.html`);
    expect(res.status).toBe(404);
  });

  it('rebuilds and sends a reload message when content changes', async () => {
    writeTree(root, {
      'content/a.md': '---\ntitle: A\n---\nHello.',
    });
    build({ contentDir, outputDir, templateDir });

    dev = startDevServer({ contentDir, outputDir, templateDir, port: 0 });
    const port = await listen(dev.server);

    const ws = new WebSocket(`ws://127.0.0.1:${port}/__live_reload`);
    await new Promise<void>((resolve) => ws.once('open', () => resolve()));

    fs.writeFileSync(path.join(contentDir, 'b.md'), '---\ntitle: B\n---\nNew page.');

    const msg = await waitForMessage(ws);
    expect(msg).toBe('reload');
    await waitForFile(path.join(outputDir, 'b.html'));

    ws.close();
  });

  it('rebuilds and sends a reload message when templates change', async () => {
    writeTree(root, {
      'content/a.md': '---\ntitle: A\n---\nHello.',
      'templates/default.hbs': '<article>{{title}} v1</article>',
      'templates/layouts/default.hbs': '<html><head></head><body>{{{body}}}</body></html>',
    });
    build({ contentDir, outputDir, templateDir });

    dev = startDevServer({ contentDir, outputDir, templateDir, port: 0 });
    const port = await listen(dev.server);

    const ws = new WebSocket(`ws://127.0.0.1:${port}/__live_reload`);
    await new Promise<void>((resolve) => ws.once('open', () => resolve()));

    fs.writeFileSync(path.join(templateDir, 'default.hbs'), '<article>{{title}} v2</article>');

    const msg = await waitForMessage(ws);
    expect(msg).toBe('reload');

    ws.close();
  });
});

