function waitForFile(filePath: string, timeout = 8000): Promise<void> {
  return new Promise((resolve, reject) => {
    const start = Date.now();
    const timer = setInterval(() => {
      if (fs.existsSync(filePath)) {
        clearInterval(timer);
        resolve();
      } else if (Date.now() - start > timeout) {
        clearInterval(timer);
        reject(new Error(`timed out waiting for ${filePath}`));
      }
    }, 50);
  });
}

const CLOSE_HEADERS = { connection: 'close' };

async function get(port: number, pathname: string): Promise<{ status: number; body: string }> {
  const res = await fetch(`http://127.0.0.1:${port}${pathname}`, { headers: CLOSE_HEADERS });
  const body = await res.text();
  return { status: res.status, body };
}

